/**
 * AvaKitMessenger creation bytecode — the same self-contained send/receive ICM
 * contract as the icm-messenger template. Studio deploys it with `cast` so you
 * can send a cross-chain message without leaving the dashboard.
 *
 * The bytecode is generated from
 * packages/create-avalanche-app/templates/icm-messenger/contracts — do not edit
 * it by hand. After that contract changes, regenerate it with
 *   cd contracts-ci && node scripts/check-artifacts.mjs --write
 * CI fails if it drifts from that source, or if one of the *_SIG constants
 * below names something the contract does not have.
 *
 * The contract rejects messages longer than 256 bytes of UTF-8
 * (MAX_MESSAGE_LENGTH), so a delivery always fits its gas budget.
 */

export const MESSENGER_BYTECODE =
  "" as const;

/**
 * The canonical TeleporterMessenger predeploy. The messenger takes its chain's
 * Teleporter as a constructor argument; on avalanche-cli local devnets that is
 * always this address.
 */
export const TELEPORTER_PREDEPLOY = "0x253b2784c75e510dD0fF1da844684a1aC0aa5fcf" as const;

export const CONSTRUCTOR_SIG = "constructor(address)" as const;
export const SEND_MESSAGE_SIG = "sendMessage(bytes32,address,string)" as const;
export const SET_TRUSTED_REMOTE_SIG = "setTrustedRemote(bytes32,address)" as const;
export const TRUSTED_REMOTE_SIG = "trustedRemote(bytes32)(address)" as const;
export const LAST_MESSAGE_SIG = "lastMessage()(string)" as const;
export const MESSAGES_RECEIVED_SIG = "messagesReceived()(uint256)" as const;
